.github/workflows/ci.yml.text:
name: CI

on:
  pull_request:
    branches: [main, master]
  push:
    branches: [main, master]
  workflow_dispatch:

permissions:
  contents: read

jobs:
  verify:
    name: Gates (docs/code/assets/godot)
    runs-on: ubuntu-24.04
    timeout-minutes: 20
    steps:
      - uses: actions/checkout@v6
        with:
          fetch-depth: 0
      - uses: actions/setup-python@v6
        with:
          python-version: "3.12.8"
      - uses: chickensoft-games/setup-godot@v2
        with:
          version: "4.7.2"
          use-dotnet: false
      - name: Install pinned gdtoolkit
        run: python -m pip install "gdtoolkit==4.5.0"
      - name: Run local CI gates
        run: >
          python tools/ci/run_local.py --rounds 1
          --skip scope,policy_tightening

  scope:
    name: Scope and policy budget (git diff)
    if: github.event_name == 'pull_request'
    runs-on: ubuntu-24.04
    timeout-minutes: 10
    permissions:
      contents: read
    steps:
      - uses: actions/checkout@v6
        with:
          fetch-depth: 0
      - uses: actions/setup-python@v6
        with:
          python-version: "3.12.8"
      - name: Check allowed paths and file/line budget
        run: python tools/ci/check_scope.py --base "$BASE_SHA" --head "$HEAD_SHA"
        env:
          BASE_SHA: ${{ github.event.pull_request.base.sha }}
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
      - name: Check policy only tightens
        run: python tools/ci/check_policy_tightening.py --base "$BASE_SHA"
        env:
          BASE_SHA: ${{ github.event.pull_request.base.sha }}
      - name: Check protected tests were not deleted
        run: >
          python tools/ci/check_protected_tests.py
          --base "$BASE_SHA" --head "$HEAD_SHA"
        env:
          BASE_SHA: ${{ github.event.pull_request.base.sha }}
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}

  policy-approval:
    name: Policy approval
    if: github.event_name == 'pull_request'
    runs-on: ubuntu-24.04
    timeout-minutes: 10
    permissions:
      contents: read
      pull-requests: read
    steps:
      - uses: actions/checkout@v6
      - uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');
            const policy = JSON.parse(fs.readFileSync('ci/policy.json', 'utf8'));
            const { owner, repo } = context.repo;
            const pr = context.payload.pull_request;
            const files = await github.paginate(github.rest.pulls.listFiles, {
              owner,
              repo,
              pull_number: pr.number,
              per_page: 100,
            });
            const touchesPolicy = files.some((file) =>
              policy.policy_paths.some(
                (path) => file.filename === path || file.filename.startsWith(path)
              )
            );
            if (!touchesPolicy) {
              core.info('No CI policy / protected files touched; approval not required.');
              return;
            }
            if (pr.user.login === policy.policy_approver) {
              core.setFailed(
                `Policy files may not be self-approved: PR author @${pr.user.login} is the policy approver.`
              );
              return;
            }
            const reviews = await github.paginate(github.rest.pulls.listReviews, {
              owner,
              repo,
              pull_number: pr.number,
              per_page: 100,
            });
            const latest = new Map();
            for (const review of reviews) {
              latest.set(review.user.login, review);
            }
            const approval = latest.get(policy.policy_approver);
            if (
              !approval ||
              approval.state !== 'APPROVED' ||
              approval.commit_id !== pr.head.sha
            ) {
              core.setFailed(
                `CI policy / protected files changed. Requires an APPROVED review from ` +
                  `@${policy.policy_approver} (not the PR author) on the current head ` +
                  `${pr.head.sha}.`
              );
              return;
            }
            core.info(`Policy change approved by @${policy.policy_approver}.`);

scripts/autoload/game_state.gd.text:
extends Node
## 全局游戏状态（autoload GameState）。
## 纯逻辑：不依赖场景，测试里可直接 GameStateScript.new() 后调用 new_game()。
## 时间、耕作、背包、出货、社交、存档都从这里走；HUD 直接读字段。

signal changed
signal message(text: String)
signal day_started(summary: Dictionary)

const Inventory = preload("res://scripts/systems/inventory.gd")
const Farming = preload("res://scripts/systems/farming.gd")
const SaveSystem = preload("res://scripts/systems/save_system.gd")
const Items = preload("res://scripts/data/items.gd")
const Crops = preload("res://scripts/data/crops.gd")
const Parity = preload("res://scripts/data/parity.gd")

const SAVE_PATH := "user://savegame.json"
const FARM_SCENE := "res://scenes/main.tscn"
const HOUSE_SCENE := "res://scenes/farmhouse.tscn"

var save_path: String = SAVE_PATH
var day: int = 1
var season: int = 0
var year: int = 1
var minutes: int = Parity.START_MINUTES
var gold: int = Parity.START_GOLD
var energy: float = Parity.MAX_ENERGY
var water: int = Parity.WATER_CAN_CAPACITY
var inventory
var plots: Dictionary = {}
var shipping: Dictionary = {}
var friendship: int = 0
var talked_today: bool = false
var selected_slot: int = 0
var paused: bool = false
var play_seconds: float = 0.0
var current_scene: String = "farm"
var spawn_cell: Vector2i = Vector2i(15, 12)
var last_summary: Dictionary = {}
var initialized: bool = false


func _ready() -> void:
	inventory = Inventory.new(Parity.INVENTORY_SLOTS)
	if not load_game():
		new_game()
	initialized = true


func _process(delta: float) -> void:
	if not initialized or paused:
		return
	play_seconds += delta
	while play_seconds >= Parity.TICK_SECONDS:
		play_seconds -= Parity.TICK_SECONDS
		minutes += Parity.TICK_MINUTES
		changed.emit()
		if minutes >= Parity.DAY_END_MINUTES:
			pass_out()
			break


func new_game() -> void:
	day = 1
	season = 0
	year = 1
	minutes = Parity.START_MINUTES
	gold = Parity.START_GOLD
	energy = Parity.MAX_ENERGY
	water = Parity.WATER_CAN_CAPACITY
	inventory = Inventory.new(Parity.INVENTORY_SLOTS)
	inventory.setup_starting()
	plots = {}
	shipping = {}
	friendship = 0
	talked_today = false
	selected_slot = 0
	play_seconds = 0.0
	current_scene = "farm"
	spawn_cell = Vector2i(15, 12)
	changed.emit()


func spend_energy(cost: float) -> bool:
	if cost <= 0.0:
		return true
	if energy < cost:
		message.emit("太累了，回农舍睡一觉吧。")
		return false
	energy -= cost
	changed.emit()
	return true


# ---------------- 耕地 / 作物 ----------------


func till(cell: Vector2i) -> bool:
	if not spend_energy(float(Parity.TOOL_ENERGY["hoe"])):
		return false
	if not Farming.till(plots, cell):
		energy += float(Parity.TOOL_ENERGY["hoe"])
		return false
	changed.emit()
	return true


func water_plot(cell: Vector2i) -> bool:
	if water <= 0:
		message.emit("浇水壶里没水了，去池塘边补满。")
		return false
	if not spend_energy(float(Parity.TOOL_ENERGY["watering_can"])):
		return false
	if not Farming.water(plots, cell):
		energy += float(Parity.TOOL_ENERGY["watering_can"])
		return false
	water -= 1
	changed.emit()
	return true


func refill_can() -> bool:
	if water >= Parity.WATER_CAN_CAPACITY:
		return false
	water = Parity.WATER_CAN_CAPACITY
	changed.emit()
	return true


func plant(cell: Vector2i, seed_id: String) -> bool:
	var item: Dictionary = Items.get_item(seed_id)
	var crop_id := String(item.get("crop", ""))
	if crop_id == "" or not Crops.can_plant_in(crop_id, season):
		return false
	if inventory.count(seed_id) <= 0:
		message.emit("没有可播种的种子。")
		return false
	if not Farming.plant(plots, cell, crop_id):
		return false
	inventory.remove(seed_id, 1)
	changed.emit()
	return true


func harvest(cell: Vector2i) -> bool:
	var plot: Dictionary = Farming.plot(plots, cell)
	var crop_id := String(plot.get("crop", ""))
	if crop_id == "" or int(plot.get("growth", 0)) < Crops.days_to_grow(crop_id):
		return false
	var harvest_id := Crops.harvest_id(crop_id)
	if not inventory.can_add(harvest_id, 1):
		message.emit("背包满了，无法收获。")
		return false
	if Farming.harvest(plots, cell) == "":
		return false
	inventory.add(harvest_id, 1)
	changed.emit()
	return true


# ---------------- 背包 / 经济 / 社交 ----------------


func add_item(id: String, count: int) -> bool:
	if inventory.add(id, count) != 0:
		message.emit("背包满了。")
		return false
	changed.emit()
	return true


func ship_selected() -> bool:
	var slot: Dictionary = inventory.selected(selected_slot)
	if slot.is_empty() or Items.is_tool_item(String(slot["id"])):
		message.emit("只能把作物或材料放进出货箱。")
		return false
	var id := String(slot["id"])
	var amount := int(slot["count"])
	shipping[id] = int(shipping.get(id, 0)) + amount
	inventory.remove(id, amount)
	changed.emit()
	message.emit("%s x%d 已放进出货箱，明早结算。" % [Items.display_name(id), amount])
	return true


func buy(id: String, price: int) -> bool:
	if gold < price:
		message.emit("金币不够。")
		return false
	if not Items.exists(id):
		return false
	if inventory.add(id, 1) != 0:
		message.emit("背包满了。")
		return false
	gold -= price
	changed.emit()
	return true


func talk() -> bool:
	if talked_today:
		return false
	talked_today = true
	friendship = mini(Parity.FRIENDSHIP_MAX, friendship + Parity.FRIENDSHIP_TALK)
	changed.emit()
	return true


# ---------------- 日推进 / 睡觉 / 昏倒 ----------------


func advance_day(slept: bool, energy_after: float = -1.0) -> void:
	var income: int = 0
	for id: String in shipping.keys():
		income += Items.sell_price(id) * int(shipping[id])
	gold += income
	shipping = {}
	Farming.grow_overnight(plots)
	var season_changed := false
	day += 1
	if day > Parity.SEASON_DAYS:
		day = 1
		season += 1
		season_changed = true
		if season >= 4:
			season = 0
			year += 1
		plots = {}
	minutes = Parity.START_MINUTES
	water = Parity.WATER_CAN_CAPACITY
	play_seconds = 0.0
	talked_today = false
	energy = Parity.MAX_ENERGY if energy_after < 0.0 else energy_after
	last_summary = {
		"day": day,
		"season": season,
		"year": year,
		"income": income,
		"season_changed": season_changed,
	}
	if slept:
		save_game()
	day_started.emit(last_summary)
	changed.emit()


func sleep() -> void:
	advance_day(true)


func pass_out() -> void:
	var penalty: int = mini(int(gold * Parity.PASSOUT_GOLD_RATE), Parity.PASSOUT_GOLD_MAX)
	gold = maxi(0, gold - penalty)
	message.emit("你在凌晨两点昏倒了……医药费 %d 金币。" % penalty)
	advance_day(true, Parity.PASSOUT_ENERGY)


func change_scene(target: String) -> void:
	if target == "house":
		current_scene = "house"
		spawn_cell = Vector2i(7, 8)
		get_tree().change_scene_to_file(HOUSE_SCENE)
	else:
		current_scene = "farm"
		spawn_cell = Vector2i(15, 11)
		get_tree().change_scene_to_file(FARM_SCENE)


# ---------------- 存档 ----------------


func to_data() -> Dictionary:
	return SaveSystem.to_data(self)


func from_data(data: Dictionary) -> bool:
	if not SaveSystem.from_data(self, data):
		return false
	changed.emit()
	return true


func save_game() -> bool:
	var file := FileAccess.open(save_path, FileAccess.WRITE)
	if file == null:
		return false
	file.store_string(JSON.stringify(to_data(), "\t"))
	return true


func load_game() -> bool:
	if not FileAccess.file_exists(save_path):
		return false
	var file := FileAccess.open(save_path, FileAccess.READ)
	if file == null:
		return false
	var parsed: Variant = JSON.parse_string(file.get_as_text())
	if not parsed is Dictionary:
		return false
	return from_data(parsed)

scripts/data/crops.gd.text:
extends RefCounted
## 作物定义。days=成熟所需天数；stages=生长阶段数；seasons=可种植季节（0 春）。

const CROPS := {
	"parsnip":
	{
		"name": "防风草",
		"seed": "parsnip_seed",
		"harvest": "parsnip",
		"days": 4,
		"stages": 4,
		"seasons": [0],
		"sell": 35,
		"seed_price": 20,
	},
}


static func get_crop(id: String) -> Dictionary:
	return CROPS.get(id, {})


static func days_to_grow(id: String) -> int:
	return int(get_crop(id).get("days", 0))


static func harvest_id(id: String) -> String:
	return String(get_crop(id).get("harvest", ""))


static func seed_id(id: String) -> String:
	return String(get_crop(id).get("seed", ""))


static func can_plant_in(id: String, season: int) -> bool:
	var seasons: Array = get_crop(id).get("seasons", [])
	return seasons.has(season)


static func harvest_yield(_id: String) -> int:
	return 1

scripts/systems/farming.gd.text:
extends RefCounted
## 地块与作物状态机（纯数据，不触碰场景 / 背包 / 能量）。
## plot = {"crop": String, "growth": int, "watered": bool}；plots 的 key 为 "x,y"。

const Crops = preload("res://scripts/data/crops.gd")


static func key(cell: Vector2i) -> String:
	return "%d,%d" % [cell.x, cell.y]


static func plot(plots: Dictionary, cell: Vector2i) -> Dictionary:
	return plots.get(key(cell), {})


static func till(plots: Dictionary, cell: Vector2i) -> bool:
	if plots.has(key(cell)):
		return false
	plots[key(cell)] = {"crop": "", "growth": 0, "watered": false}
	return true


static func water(plots: Dictionary, cell: Vector2i) -> bool:
	var entry: Dictionary = plots.get(key(cell), {})
	if entry.is_empty() or bool(entry["watered"]):
		return false
	entry["watered"] = true
	plots[key(cell)] = entry
	return true


static func plant(plots: Dictionary, cell: Vector2i, crop_id: String) -> bool:
	var entry: Dictionary = plots.get(key(cell), {})
	if entry.is_empty() or String(entry["crop"]) != "":
		return false
	if not Crops.CROPS.has(crop_id):
		return false
	entry["crop"] = crop_id
	entry["growth"] = 0
	plots[key(cell)] = entry
	return true


## 返回收获物品 id；未成熟或空地返回空串。
static func harvest(plots: Dictionary, cell: Vector2i) -> String:
	var entry: Dictionary = plots.get(key(cell), {})
	if entry.is_empty():
		return ""
	var crop_id := String(entry["crop"])
	if crop_id == "" or int(entry["growth"]) < Crops.days_to_grow(crop_id):
		return ""
	entry["crop"] = ""
	entry["growth"] = 0
	entry["watered"] = false
	plots[key(cell)] = entry
	return Crops.harvest_id(crop_id)


## 过夜：只有当天浇过水的作物才成长。浇水状态每天清空。
static func grow_overnight(plots: Dictionary) -> void:
	for entry_key: String in plots.keys():
		var entry: Dictionary = plots[entry_key]
		var crop_id := String(entry["crop"])
		if crop_id != "" and bool(entry["watered"]):
			entry["growth"] = mini(int(entry["growth"]) + 1, Crops.days_to_grow(crop_id))
		entry["watered"] = false
		plots[entry_key] = entry


static func stage(plot_entry: Dictionary) -> int:
	if plot_entry.is_empty():
		return 0
	if String(plot_entry["crop"]) == "":
		return 0
	return clampi(int(plot_entry["growth"]), 0, 4)

scripts/systems/inventory.gd.text:
extends RefCounted
## 12 格工具栏背包：工具不可堆叠，物品按 999 堆叠。
## 纯数据对象，不依赖场景树，便于无头测试。

const Items = preload("res://scripts/data/items.gd")

var size: int = 12
var slots: Array = []


func _init(slot_count: int = 12) -> void:
	size = slot_count
	slots.clear()
	for _i in range(size):
		slots.append({})


## 初始装备：5 件工具 + 15 粒防风草种子（与星露谷新档一致）。
func setup_starting() -> void:
	slots.clear()
	for _i in range(size):
		slots.append({})
	var tools := ["hoe", "watering_can", "axe", "pickaxe", "scythe"]
	for i in range(tools.size()):
		slots[i] = {"id": tools[i], "count": 1}
	add("parsnip_seed", 15)


## 返回未能放入的数量（0 表示全部放入）。
func add(id: String, count: int) -> int:
	if not Items.exists(id) or count <= 0:
		return count
	var stack_max := _stack_max(id)
	return _fill_empty(id, _merge_existing(id, count, stack_max), stack_max)


func can_add(id: String, count: int) -> bool:
	if count <= 0:
		return true
	if not Items.exists(id):
		return false
	var stack_max := _stack_max(id)
	var left := count
	for i in range(size):
		var slot: Dictionary = slots[i]
		if slot.get("id", "") == id:
			left -= maxi(0, stack_max - int(slot["count"]))
	for i in range(size):
		if slots[i].is_empty():
			left -= stack_max
	return left <= 0


func remove(id: String, count: int) -> bool:
	if count <= 0 or count(id) < count:
		return false
	var left := count
	for i in range(size):
		if left <= 0:
			break
		var slot: Dictionary = slots[i]
		if slot.get("id", "") != id:
			continue
		var taken: int = mini(int(slot["count"]), left)
		slot["count"] = int(slot["count"]) - taken
		left -= taken
		slots[i] = {} if int(slot["count"]) <= 0 else slot
	return true


func count(id: String) -> int:
	var total := 0
	for i in range(size):
		var slot: Dictionary = slots[i]
		if slot.get("id", "") == id:
			total += int(slot["count"])
	return total


func is_empty() -> bool:
	for i in range(size):
		if not slots[i].is_empty():
			return false
	return true


func has_free_slot() -> bool:
	return first_empty() >= 0


func first_empty() -> int:
	for i in range(size):
		if slots[i].is_empty():
			return i
	return -1


## 选中格：索引始终合法（0..size-1）。
func selected(selected_index: int) -> Dictionary:
	if selected_index < 0 or selected_index >= size:
		return {}
	return slots[selected_index]


func swap(a: int, b: int) -> void:
	if a < 0 or b < 0 or a >= size or b >= size or a == b:
		return
	var tmp: Dictionary = slots[a]
	slots[a] = slots[b]
	slots[b] = tmp


func to_array() -> Array:
	return slots.duplicate(true)


func from_array(data: Array) -> bool:
	if data.size() != size:
		return false
	var restored: Array = []
	for i in range(size):
		var entry: Variant = data[i]
		if entry == null or not entry is Dictionary:
			restored.append({})
			continue
		var id := String(entry.get("id", ""))
		var amount := int(entry.get("count", 0))
		if id == "" or amount <= 0:
			restored.append({})
			continue
		restored.append({"id": id, "count": amount})
	slots = restored
	return true


func _stack_max(id: String) -> int:
	return 1 if Items.is_tool_item(id) else 999


func _merge_existing(id: String, count: int, stack_max: int) -> int:
	var left := count
	for i in range(size):
		if left <= 0:
			break
		var slot: Dictionary = slots[i]
		if slot.get("id", "") != id:
			continue
		var room: int = stack_max - int(slot["count"])
		if room <= 0:
			continue
		var moved: int = mini(room, left)
		slot["count"] = int(slot["count"]) + moved
		slots[i] = slot
		left -= moved
	return left


func _fill_empty(id: String, left: int, stack_max: int) -> int:
	for i in range(size):
		if left <= 0:
			break
		if not slots[i].is_empty():
			continue
		var moved: int = mini(stack_max, left)
		slots[i] = {"id": id, "count": moved}
		left -= moved
	return left

scripts/world/actions.gd.text:
extends RefCounted
## 场景输入与工具/互动动作（从 WorldScene 拆出，控制单文件规模与圈复杂度）。

const Items = preload("res://scripts/data/items.gd")
const Parity = preload("res://scripts/data/parity.gd")


static func handle_input(scene, event: InputEvent) -> void:
	if scene.hud == null:
		return
	if event.is_action_pressed("pause_game"):
		if scene.hud.is_modal() and scene.hud.modal_kind() != "pause":
			scene.hud.close_modal()
		else:
			scene.hud.toggle_pause()
		return
	if scene.hud.is_modal():
		_handle_modal(scene, event)
		return
	if event.is_action_pressed("toggle_help"):
		scene.hud.toggle_help()
	elif event.is_action_pressed("use_tool"):
		use_selected(scene)
	elif event.is_action_pressed("interact"):
		interact(scene)
	else:
		_handle_hotbar(scene, event)


static func _handle_modal(scene, event: InputEvent) -> void:
	if event.is_action_pressed("interact") or event.is_action_pressed("confirm"):
		scene.hud.close_modal()
		return
	var key_event := false
	if event is InputEventKey:
		var key := event as InputEventKey
		key_event = key.pressed and key.physical_keycode == KEY_B
	if key_event and scene.hud.modal_kind() == "dialogue":
		scene.hud.open_shop()


static func _handle_hotbar(scene, event: InputEvent) -> void:
	for i in range(Parity.INVENTORY_SLOTS):
		if event.is_action_pressed("hotbar_%d" % (i + 1)):
			GameState.selected_slot = i
			scene.hud.refresh()
			return


static func use_selected(scene) -> void:
	var slot: Dictionary = GameState.inventory.selected(GameState.selected_slot)
	if slot.is_empty():
		scene.hud.show_message("当前栏位是空的。")
		return
	var id := String(slot["id"])
	var item: Dictionary = Items.get_item(id)
	var cell: Vector2i = scene.player.facing_cell()
	match String(item.get("kind", "")):
		"tool":
			use_tool(scene, String(item.get("tool", "")), cell)
		"seed":
			plant(scene, cell, id)
		_:
			scene.hud.show_message("「%s」不能直接使用。" % Items.display_name(id))
	scene.hud.refresh()


static func use_tool(scene, tool: String, cell: Vector2i) -> void:
	if not scene._allows_farming():
		scene.hud.show_message("屋里不能使用农具。")
		return
	match tool:
		"hoe":
			do_till(scene, cell)
		"watering_can":
			do_water(scene, cell)
		"axe":
			hit_object(scene, cell, "tree", "axe")
		"pickaxe":
			hit_object(scene, cell, "stone", "pickaxe")
		"scythe":
			hit_object(scene, cell, "weed", "scythe")
		_:
			scene.hud.show_message("这个工具暂时用不了。")


static func do_till(scene, cell: Vector2i) -> void:
	if GameState.till(cell):
		scene.hud.show_message("翻好了一块地，可以播种了。")
	else:
		scene.hud.show_message("这里不能开垦。")


static func do_water(scene, cell: Vector2i) -> void:
	if scene.water_cells.has(scene.cell_key(cell)):
		if GameState.refill_can():
			scene.hud.show_message("浇水壶补满了。")
		else:
			scene.hud.show_message("浇水壶已经是满的。")
		return
	if GameState.water_plot(cell):
		scene.hud.show_message("浇水完成。")
	else:
		scene.hud.show_message("这里没有可以浇水的耕地。")


static func plant(scene, cell: Vector2i, seed_id: String) -> void:
	if GameState.plant(cell, seed_id):
		scene.hud.show_message("种下了种子。")
	else:
		scene.hud.show_message("需要一块已开垦的空地，且背包里有种子。")


static func hit_object(scene, cell: Vector2i, kind: String, tool: String) -> void:
	var key: String = scene.cell_key(cell)
	var entry: Dictionary = scene.objects.get(key, {})
	if entry.is_empty() or String(entry["kind"]) != kind:
		scene.hud.show_message("这里没有可以采集的东西。")
		return
	if not GameState.spend_energy(float(Parity.TOOL_ENERGY.get(tool, 2.0))):
		return
	entry["hp"] = int(entry["hp"]) - 1
	if int(entry["hp"]) > 0:
		scene.objects[key] = entry
		scene.hud.show_message("还需要再敲 %d 下。" % int(entry["hp"]))
		return
	_clear_object(scene, key, entry)


static func _clear_object(scene, key: String, entry: Dictionary) -> void:
	var node: Node2D = entry["node"]
	if is_instance_valid(node):
		node.queue_free()
	scene.objects.erase(key)
	scene.blocked.erase(key)
	var drop := String(entry["drop"])
	var count := int(entry["count"])
	GameState.add_item(drop, count)
	scene.hud.show_message("收集到 %s x%d。" % [Items.display_name(drop), count])


static func interact(scene) -> void:
	var cell: Vector2i = scene.player.facing_cell()
	if scene._interact_world(cell):
		return
	scene.hud.show_message("这里没有可以互动的东西。")

scripts/world/farm.gd.text:
extends WorldScene
## 第一个主场景：标准农场（80x65）。农舍、出货箱、池塘、温室残骸、森林边界与可采集物。

const VillagerScript = preload("res://scripts/world/villager.gd")

const HOUSE_RECT := Rect2i(12, 6, 7, 4)
const DOOR_CELL := Vector2i(15, 9)
const BIN_CELL := Vector2i(19, 11)
const MAILBOX_CELL := Vector2i(13, 11)
const GREENHOUSE_RECT := Rect2i(57, 6, 7, 5)
const VILLAGER_CELL := Vector2i(22, 12)
const SCATTER_SEED := 20261028

var villager
var path_cells: Dictionary = {}


func _build_world() -> void:
	_prepare_layers()
	_fill_grass()
	_build_paths()
	_build_pond()
	_build_house_exterior()
	_build_greenhouse()
	_build_borders()
	_scatter_objects()
	_build_fixtures()
	_build_villager()


func _allows_farming() -> bool:
	return true


func _fill_grass() -> void:
	for x in range(map_size.x):
		for y in range(map_size.y):
			var index := 0 if (x * 7 + y * 13) % 5 != 0 else 1
			_set_ground(Vector2i(x, y), index)


func _build_paths() -> void:
	for y in range(10, map_size.y):
		_mark_path(Vector2i(15, y))
	for x in range(15, 24):
		_mark_path(Vector2i(x, 12))
	for y in range(6, 13):
		_mark_path(Vector2i(19, y))


func _mark_path(cell: Vector2i) -> void:
	path_cells[cell_key(cell)] = true
	_set_ground(cell, 2)


func _build_pond() -> void:
	for x in range(4, 26):
		for y in range(40, 60):
			var dx := (x - 14) / 10.0
			var dy := (y - 50) / 6.0
			if dx * dx + dy * dy <= 1.0:
				water_cells[cell_key(Vector2i(x, y))] = true
				_block_cell(Vector2i(x, y))
				_set_ground(Vector2i(x, y), 5)


func _build_house_exterior() -> void:
	_block_rect(HOUSE_RECT)
	var base := Vector2(
		HOUSE_RECT.position.x * 16.0, (HOUSE_RECT.position.y + HOUSE_RECT.size.y) * 16.0
	)
	var node := Node2D.new()
	node.position = base
	var sprite := Sprite2D.new()
	sprite.texture = Art.house_texture()
	sprite.centered = false
	sprite.position = Vector2(0, -64)
	sprite.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
	node.add_child(sprite)
	object_root.add_child(node)


func _build_greenhouse() -> void:
	_block_rect(GREENHOUSE_RECT)
	for x in range(GREENHOUSE_RECT.position.x, GREENHOUSE_RECT.position.x + GREENHOUSE_RECT.size.x):
		for y in range(
			GREENHOUSE_RECT.position.y, GREENHOUSE_RECT.position.y + GREENHOUSE_RECT.size.y
		):
			_add_sprite(Vector2i(x, y), 5)


func _build_borders() -> void:
	for x in range(map_size.x):
		for y in range(2):
			_block_cell(Vector2i(x, y))
			_block_cell(Vector2i(x, map_size.y - 1 - y))
	for y in range(map_size.y):
		for x in range(2):
			_block_cell(Vector2i(x, y))
			_block_cell(Vector2i(map_size.x - 1 - x, y))
	for x in range(2, map_size.x - 2, 2):
		_add_sprite(Vector2i(x, 2), 0)
		_add_sprite(Vector2i(x, map_size.y - 3), 0)
	for y in range(2, map_size.y - 2, 2):
		_add_sprite(Vector2i(2, y), 0)
		_add_sprite(Vector2i(map_size.x - 3, y), 0)


func _scatter_objects() -> void:
	var rng := RandomNumberGenerator.new()
	rng.seed = SCATTER_SEED
	var placed := 0
	var attempts := 0
	while placed < 70 and attempts < 400:
		attempts += 1
		var cell := Vector2i(rng.randi_range(4, map_size.x - 5), rng.randi_range(4, map_size.y - 5))
		var key := cell_key(cell)
		if blocked.has(key) or path_cells.has(key) or water_cells.has(key):
			continue
		if _near_start(cell):
			continue
		var roll := rng.randf()
		if roll < 0.45:
			_register_object(cell, "tree", 3, 0, "wood", 3)
		elif roll < 0.8:
			_register_object(cell, "stone", 3, 1, "stone", 2)
		else:
			_register_object(cell, "weed", 1, 2, "fiber", 1)
		placed += 1


func _near_start(cell: Vector2i) -> bool:
	if absi(cell.x - 15) <= 3 and cell.y >= 6 and cell.y <= 16:
		return true
	return false


func _build_fixtures() -> void:
	_register_object(BIN_CELL, "bin", 1, 3, "wood", 0)
	_block_cell(MAILBOX_CELL)
	_add_sprite(MAILBOX_CELL, 4)


func _build_villager() -> void:
	villager = VillagerScript.new()
	villager.position = cell_center(VILLAGER_CELL)
	_block_cell(VILLAGER_CELL)
	object_root.add_child(villager)


func _interact_world(cell: Vector2i) -> bool:
	if villager != null and player.global_position.distance_to(villager.global_position) <= 32.0:
		hud.show_dialogue("林婶", villager.talk_line(), true)
		GameState.talk()
		return true
	if cell == DOOR_CELL:
		GameState.change_scene("house")
		return true
	if cell == BIN_CELL:
		GameState.ship_selected()
		return true
	if cell == MAILBOX_CELL:
		hud.show_message("邮箱里只有一封镇长的欢迎信：先种下 15 粒防风草种子吧。")
		return true
	return false

