extends WorldScene
## 农舍内部：木地板房间、床（睡觉推进到第二天）、出口门回农场。

const ROOM_SIZE := Vector2i(14, 10)
const DOOR_CELL := Vector2i(7, 9)
const BED_CELLS := [Vector2i(3, 2), Vector2i(4, 2), Vector2i(3, 3), Vector2i(4, 3)]
const SPAWN_CELL := Vector2i(7, 8)


func _build_world() -> void:
	map_size = ROOM_SIZE
	_prepare_layers()
	var background := ColorRect.new()
	background.color = Color("1a120c")
	background.position = Vector2(-80, -80)
	background.size = Vector2(map_size.x * 16.0 + 160.0, map_size.y * 16.0 + 160.0)
	background.z_index = -20
	add_child(background)
	for x in range(map_size.x):
		for y in range(map_size.y):
			_set_ground(Vector2i(x, y), 7)
	_build_walls()
	_build_bed()
	_build_door()


func _build_walls() -> void:
	for x in range(map_size.x):
		for y in range(map_size.y):
			if x == 0 or y == 0 or x == map_size.x - 1 or y == map_size.y - 1:
				_block_cell(Vector2i(x, y))
				_set_ground(Vector2i(x, y), 6)


func _camera_zoom() -> float:
	return 2.0


func _build_bed() -> void:
	for cell in BED_CELLS:
		_block_cell(cell)
	var node := Node2D.new()
	node.position = Vector2(3 * 16.0, 2 * 16.0)
	var frame := ColorRect.new()
	frame.color = Color("6b4a2a")
	frame.size = Vector2(32, 32)
	node.add_child(frame)
	var sheet := ColorRect.new()
	sheet.color = Color("d94a4a")
	sheet.position = Vector2(2, 2)
	sheet.size = Vector2(28, 20)
	node.add_child(sheet)
	var pillow := ColorRect.new()
	pillow.color = Color("f4f4f4")
	pillow.position = Vector2(4, 3)
	pillow.size = Vector2(24, 6)
	node.add_child(pillow)
	object_root.add_child(node)


func _build_door() -> void:
	_block_cell(DOOR_CELL)
	var node := Node2D.new()
	node.position = Vector2(DOOR_CELL.x * 16.0, DOOR_CELL.y * 16.0)
	var door := ColorRect.new()
	door.color = Color("8b5a2b")
	door.size = Vector2(16, 16)
	node.add_child(door)
	object_root.add_child(node)


func _interact_world(cell: Vector2i) -> bool:
	if cell == DOOR_CELL:
		GameState.change_scene("farm")
		return true
	for bed_cell in BED_CELLS:
		if cell == bed_cell:
			GameState.sleep()
			return true
	return false

scripts/world/player.gd.text:
class_name Player
extends CharacterBody2D
## 玩家：四方向行走 + 逐帧动画。碰撞采用瓦片网格阻挡检查（block_check 回调）。

const Art = preload("res://scripts/world/art.gd")

const SPEED := 84.0
const HALF := Vector2(5, 4)

var facing := Vector2i.DOWN
var block_check: Callable = Callable()
var can_move := true
var sprite: Sprite2D
var camera: Camera2D
var walk_time := 0.0


func _ready() -> void:
	sprite = Sprite2D.new()
	sprite.texture = Art.character_texture(false)
	sprite.hframes = 4
	sprite.vframes = 4
	sprite.frame = 1
	sprite.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
	add_child(sprite)
	camera = Camera2D.new()
	camera.position = Vector2.ZERO
	add_child(camera)


func _physics_process(delta: float) -> void:
	if not can_move:
		walk_time = 0.0
		_update_frame()
		return
	var input := Input.get_vector("move_left", "move_right", "move_up", "move_down")
	if input.length() < 0.1:
		walk_time = 0.0
		_update_frame()
		return
	_set_facing(input)
	walk_time += delta
	var target := global_position + input.normalized() * SPEED * delta
	_move_toward(target)
	_update_frame()


func facing_cell() -> Vector2i:
	return Vector2i(floori(global_position.x / 16.0), floori(global_position.y / 16.0)) + facing


func _move_toward(target: Vector2) -> void:
	if _can_walk(target):
		global_position = target
		return
	var axis_x := Vector2(target.x, global_position.y)
	if _can_walk(axis_x):
		global_position = axis_x
	var axis_y := Vector2(global_position.x, target.y)
	if _can_walk(axis_y):
		global_position = axis_y


func _can_walk(point: Vector2) -> bool:
	if not block_check.is_valid():
		return true
	return (
		bool(block_check.call(point + Vector2(-HALF.x, -HALF.y)))
		and bool(block_check.call(point + Vector2(HALF.x, -HALF.y)))
		and bool(block_check.call(point + Vector2(-HALF.x, HALF.y)))
		and bool(block_check.call(point + Vector2(HALF.x, HALF.y)))
	)


func _set_facing(input: Vector2) -> void:
	if absf(input.x) > absf(input.y):
		facing = Vector2i.RIGHT if input.x > 0.0 else Vector2i.LEFT
	else:
		facing = Vector2i.DOWN if input.y > 0.0 else Vector2i.UP


func _update_frame() -> void:
	var row := 0
	if facing == Vector2i.LEFT:
		row = 1
	elif facing == Vector2i.RIGHT:
		row = 2
	elif facing == Vector2i.UP:
		row = 3
	var column := 1
	if walk_time > 0.0:
		column = int(walk_time * 8.0) % 4
	sprite.frame = row * 4 + column

scripts/world/villager.gd.text:
class_name Villager
extends Node2D
## 农舍旁的邻居「林婶」：固定站位、按天数/好感轮换问候。

const Art = preload("res://scripts/world/art.gd")

var sprite: Sprite2D


func _ready() -> void:
	sprite = Sprite2D.new()
	sprite.texture = Art.character_texture(true)
	sprite.hframes = 4
	sprite.vframes = 4
	sprite.frame = 1
	sprite.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
	add_child(sprite)


func line(friendship: int) -> String:
	var lines := [
		"早上好呀。农场头几天最难，先把防风草种下去吧。",
		"防风草四天就能收，记得每天浇水，不然它不会长大。",
		"浇水壶空了就去池塘边按一下，能补满。",
		"出货箱里的东西过一夜才会结算，别急着等钱。",
		"累了就回屋睡觉，凌晨两点还在外面会昏倒的。",
	]
	if friendship >= 250:
		lines.append("你已经算是村里人了，需要种子随时来找我。")
	var hearts := int(friendship / 250)
	var index: int = (GameState.day + hearts) % lines.size()
	return lines[index]


func talk_line() -> String:
	return line(GameState.friendship)

scripts/world/world_scene.gd.text:
class_name WorldScene
extends Node2D
## 场景基类：瓦片地图、玩家、HUD、阻挡格与刷新；输入分发在 actions.gd。
## 子类只负责地图内容（Farm / Farmhouse）与具体互动。

const Art = preload("res://scripts/world/art.gd")
const PlayerScript = preload("res://scripts/world/player.gd")
const HudScript = preload("res://scripts/ui/hud.gd")
const Actions = preload("res://scripts/world/actions.gd")
const Parity = preload("res://scripts/data/parity.gd")

var map_size := Parity.FARM_SIZE
var ground: TileMapLayer
var soil: TileMapLayer
var crops: TileMapLayer
var object_root: Node2D
var player
var hud
var tint: CanvasModulate
var blocked: Dictionary = {}
var objects: Dictionary = {}
var water_cells: Dictionary = {}
var tile_set: TileSet


func _ready() -> void:
	_build_world()
	_build_actors()
	_build_ui()
	GameState.paused = false
	GameState.changed.connect(_on_changed)
	GameState.day_started.connect(_on_day_started)
	_refresh()


func _process(_delta: float) -> void:
	if player != null and hud != null:
		player.can_move = not hud.is_modal()
	if tint != null:
		tint.color = _tint_color(GameState.minutes)


func _unhandled_input(event: InputEvent) -> void:
	Actions.handle_input(self, event)


# ---------------- 地图构建 ----------------


func _prepare_layers() -> void:
	tile_set = Art.build_tile_set()
	ground = _make_layer(-10)
	soil = _make_layer(-9)
	crops = _make_layer(-8)
	object_root = Node2D.new()
	object_root.y_sort_enabled = true
	add_child(object_root)
	tint = CanvasModulate.new()
	add_child(tint)


func _make_layer(z: int) -> TileMapLayer:
	var layer := TileMapLayer.new()
	layer.tile_set = tile_set
	layer.z_index = z
	layer.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
	add_child(layer)
	return layer


func _set_ground(cell: Vector2i, index: int) -> void:
	ground.set_cell(cell, 0, Vector2i(index, 0))


func _set_soil(cell: Vector2i, index: int) -> void:
	soil.set_cell(cell, 0, Vector2i(index, 0))


func _set_crop(cell: Vector2i, index: int) -> void:
	crops.set_cell(cell, 1, Vector2i(index, 0))


func _block_cell(cell: Vector2i) -> void:
	blocked[cell_key(cell)] = true


func _block_rect(rect: Rect2i) -> void:
	for x in range(rect.position.x, rect.position.x + rect.size.x):
		for y in range(rect.position.y, rect.position.y + rect.size.y):
			blocked[cell_key(Vector2i(x, y))] = true


func is_walkable(point: Vector2) -> bool:
	var cell := Vector2i(floori(point.x / 16.0), floori(point.y / 16.0))
	if cell.x < 0 or cell.y < 0 or cell.x >= map_size.x or cell.y >= map_size.y:
		return false
	return not blocked.has(cell_key(cell))


func cell_center(cell: Vector2i) -> Vector2:
	return Vector2(cell.x * 16.0 + 8.0, cell.y * 16.0 + 8.0)


func cell_key(cell: Vector2i) -> String:
	return "%d,%d" % [cell.x, cell.y]


func key_cell(key: String) -> Vector2i:
	var parts := key.split(",")
	return Vector2i(int(parts[0]), int(parts[1]))


# ---------------- 角色 / UI ----------------


func _build_actors() -> void:
	player = PlayerScript.new()
	player.position = cell_center(GameState.spawn_cell)
	player.block_check = Callable(self, "is_walkable")
	object_root.add_child(player)
	player.camera.limit_left = 0
	player.camera.limit_top = 0
	player.camera.limit_right = map_size.x * 16
	player.camera.limit_bottom = map_size.y * 16
	player.camera.limit_smoothed = true
	var zoom := _camera_zoom()
	player.camera.zoom = Vector2(zoom, zoom)


func _camera_zoom() -> float:
	return 1.0


func _build_ui() -> void:
	hud = HudScript.new()
	add_child(hud)


func _add_sprite(cell: Vector2i, atlas_index: int) -> Node2D:
	var node := Node2D.new()
	node.position = cell_center(cell)
	var sprite := Sprite2D.new()
	sprite.texture = Art.atlas_cell(Art.objects_texture(), atlas_index)
	sprite.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
	node.add_child(sprite)
	object_root.add_child(node)
	return node


func _register_object(
	cell: Vector2i, kind: String, hp: int, atlas_index: int, drop_id: String, drop_count: int
) -> void:
	_block_cell(cell)
	var node := _add_sprite(cell, atlas_index)
	objects[cell_key(cell)] = {
		"kind": kind,
		"hp": hp,
		"node": node,
		"drop": drop_id,
		"count": drop_count,
	}


# ---------------- 刷新 / 时间色调 ----------------


func _on_changed() -> void:
	_refresh_field()


func _on_day_started(summary: Dictionary) -> void:
	if hud != null:
		hud.show_day_summary(summary)
	_refresh_field()


func _refresh() -> void:
	_refresh_field()
	if hud != null:
		hud.refresh()


func _refresh_field() -> void:
	if soil == null:
		return
	soil.clear()
	crops.clear()
	for key: String in GameState.plots.keys():
		var cell := key_cell(key)
		var plot: Dictionary = GameState.plots[key]
		_set_soil(cell, 4 if bool(plot["watered"]) else 3)
		if String(plot["crop"]) != "":
			_set_crop(cell, clampi(int(plot["growth"]), 0, 4))


func _tint_color(minutes: int) -> Color:
	var hour := minutes / 60.0
	if hour < 5.0:
		return Color(0.38, 0.42, 0.72)
	if hour < 7.0:
		return Color(0.78, 0.78, 0.95)
	if hour < 17.0:
		return Color(1, 1, 1)
	if hour < 20.0:
		return Color(1.0, 0.86, 0.70)
	if hour < 24.0:
		return Color(0.58, 0.60, 0.88)
	return Color(0.40, 0.44, 0.74)


# ---------------- 子类钩子 ----------------


func _build_world() -> void:
	pass


func _allows_farming() -> bool:
	return false


func _interact_world(_cell: Vector2i) -> bool:
	return false

