tools/ci/baseline.py.text:
"""Create or refresh ``ci/baseline_snapshot.json``.

The snapshot freezes:

* the policy that future changes may only tighten against;
* the protected test cases and test files that may never be deleted;
* a content snapshot of the project used for local scope/budget checks while
  the repository has no git history.

Refreshing is a human-approved operation (``--trusted`` is required).  When the
project is connected to git, GitHub Actions uses the authorative
``--base/--head`` diff instead and this file is only a local fallback.
"""

from __future__ import annotations

import argparse
import json
import sys
from datetime import datetime, timezone

from ci_common import (
    BASELINE_PATH,
    ROOT,
    count_lines,
    iter_project_files,
    load_json,
    load_policy,
    relative,
    sha256_bytes,
)


def _manifest_cases() -> dict[str, list[str]]:
    path = ROOT / "tests/protected_test_cases.json"
    if not path.is_file():
        return {}
    data = load_json(path)
    files: dict[str, list[str]] = {}
    for name, cases in (data.get("files") or {}).items():
        files[str(name)] = [str(case) for case in cases]
    legacy_file = data.get("file")
    if legacy_file:
        bucket = files.setdefault(str(legacy_file), [])
        for case in data.get("required_assertions", []):
            if case not in bucket:
                bucket.append(str(case))
    return files


def _test_files() -> list[str]:
    tests_dir = ROOT / "tests"
    if not tests_dir.is_dir():
        return []
    return sorted(relative(path) for path in tests_dir.rglob("*.gd"))


def build_snapshot() -> dict:
    policy = load_policy()
    files: dict[str, dict] = {}
    for path in iter_project_files():
        if path == BASELINE_PATH:
            continue
        try:
            payload = path.read_bytes()
        except OSError:
            continue
        rel = relative(path)
        entry: dict = {"sha256": sha256_bytes(payload), "lines": count_lines(
            payload.decode("utf-8", "replace")
        )}
        try:
            text = payload.decode("utf-8")
            entry["text"] = text
            entry["lines"] = count_lines(text)
        except UnicodeDecodeError:
            entry["binary"] = True
        files[rel] = entry
    return {
        "schema_version": 1,
        "created_at": datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds"),
        "note": (
            "Frozen CI baseline. policy/protected_cases must never be weakened; "
            "files is the local scope baseline. Refresh only with human approval: "
            "python tools/ci/baseline.py --trusted --force"
        ),
        "policy": policy,
        "protected_cases": _manifest_cases(),
        "test_files": _test_files(),
        "files": files,
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Create/refresh CI baseline snapshot.")
    parser.add_argument("--trusted", action="store_true", help="确认已获得人工批准")
    parser.add_argument("--force", action="store_true", help="覆盖已有基线快照")
    args = parser.parse_args(argv)
    if not args.trusted:
        print(
            "拒绝执行：刷新基线需要人工批准。确认后加 --trusted（CI 中由 git 历史提供权威基线）。",
            file=sys.stderr,
        )
        return 2
    if BASELINE_PATH.exists() and not args.force:
        print(
            f"{relative(BASELINE_PATH)} 已存在；如确需刷新请加 --force。",
            file=sys.stderr,
        )
        return 2
    snapshot = build_snapshot()
    BASELINE_PATH.write_text(
        json.dumps(snapshot, ensure_ascii=False, indent=1) + "\n", encoding="utf-8"
    )
    print(
        f"已写入 {relative(BASELINE_PATH)}: "
        f"{len(snapshot['files'])} 文件, "
        f"{sum(len(cases) for cases in snapshot['protected_cases'].values())} 受保护用例, "
        f"gdtoolkit {snapshot['policy'].get('gdtoolkit_version')}"
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())

tools/ci/check_assets.py.text:
"""Asset provenance gate.

Every file under ``assets/`` must be registered in ``docs/asset_manifest.md``
inside the licence table, and the licence column must not be empty.  Generated
Godot metadata (``*.import`` / ``*.uid``), the assets README and the attached
licence texts under ``assets/licenses/`` are exempt because they are derived
or are the licence evidence itself (documented in docs/ci_rules.md).
"""

from __future__ import annotations

import re

from ci_common import ROOT, Result, load_policy, read_text, relative

NAME = "assets"
PLACEHOLDERS = {"", "-", "—", "–", "待补", "待定", "tbd", "todo", "?", "无", "n/a", "none"}


def _ignored(rel: str, policy: dict) -> bool:
    lower = rel.lower()
    for suffix in policy.get("asset_ignore_suffixes", []):
        if lower.endswith(suffix.lower()):
            return True
    if rel in policy.get("asset_ignore_files", []):
        return True
    for prefix in policy.get("asset_ignore_prefixes", []):
        if rel.startswith(prefix):
            return True
    return False


def _licence_column(manifest_text: str, headers: list[str]) -> int | None:
    for line in manifest_text.splitlines():
        if line.count("|") < 2:
            continue
        cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
        lowered = [cell.casefold() for cell in cells]
        for header in headers:
            needle = header.casefold()
            for index, cell in enumerate(lowered):
                if needle in cell:
                    return index
    return None


def _licence_cell(line: str, column: int) -> str:
    cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
    if column >= len(cells):
        return ""
    return cells[column]


def check() -> Result:
    result = Result(name=NAME)
    policy = load_policy()
    manifest_rel = policy.get("asset_manifest", "docs/asset_manifest.md")
    manifest_path = ROOT / manifest_rel

    if not manifest_path.is_file():
        result.error(
            f"素材登记清单缺失: {manifest_rel}（assets/ 下每个文件都需登记许可字段）"
        )
        return result
    text = read_text(manifest_path)
    headers = policy.get("asset_manifest_license_headers", ["许可", "License", "授权"])
    column = _licence_column(text, headers)
    if column is None:
        result.error(
            f"{manifest_rel}: 未找到许可表头（需包含 {'/'.join(headers)} 列）"
        )
        return result

    asset_files: list[str] = []
    for root in policy.get("asset_roots", ["assets"]):
        folder = ROOT / root
        if not folder.is_dir():
            result.warn(f"素材目录不存在: {root}")
            continue
        for path in sorted(folder.rglob("*")):
            if not path.is_file():
                continue
            rel = relative(path)
            if any(part.startswith(".") for part in path.relative_to(ROOT).parts):
                continue
            if _ignored(rel, policy):
                continue
            asset_files.append(rel)

    if not asset_files:
        result.note("assets/ 下没有需要登记的素材文件")
        return result

    missing: list[str] = []
    unlicensed: list[str] = []
    for rel in asset_files:
        line = next(
            (row for row in text.splitlines() if rel in row),
            None,
        )
        if line is None:
            missing.append(rel)
            continue
        value = _licence_cell(line, column).casefold().strip()
        if value in PLACEHOLDERS or re.fullmatch(r"[-—–\s]*", value):
            unlicensed.append(rel)

    for rel in missing[:20]:
        result.error(f"素材未登记: {rel}")
    if len(missing) > 20:
        result.error(f"... 其余 {len(missing) - 20} 个未登记素材未逐条列出")
    for rel in unlicensed[:20]:
        result.error(f"素材许可字段为空: {rel}")
    if len(unlicensed) > 20:
        result.error(f"... 其余 {len(unlicensed) - 20} 个空许可素材未逐条列出")

    result.note(
        f"检查 {len(asset_files)} 个素材文件（已豁免 .import/.uid/README/许可文本），"
        f"许可列索引 {column}"
    )
    return result


CHECKS = [(NAME, check)]


if __name__ == "__main__":
    import sys

    from ci_common import main_for_module

    sys.exit(main_for_module(CHECKS))

tools/ci/check_docs.py.text:
"""Documentation gate: budgets, duplicate paragraphs and version agreement.

Rules implemented (see docs/ci_rules.md):

* every core planning document exists and is at most
  ``max_core_doc_chars`` Unicode characters long;
* normalised duplicate paragraphs (whitespace-collapsed, case-folded) are
  reported inside core documents and research documents;
* research documents (``docs/research_*.md`` / ``docs/reference_*.md``) are
  exempt from the character cap but warn above ``research_doc_warn_bytes`` and
  are still checked for duplicated paragraphs;
* ``GODOT_VERSION.txt``, ``project.godot`` and ``CI.md`` must agree on the
  locked Godot build, and ``CI.md`` must record the pinned gdtoolkit version.
"""

from __future__ import annotations

import re
from pathlib import Path

from ci_common import (
    ROOT,
    Result,
    load_policy,
    read_text,
    relative,
)

NAME = "docs"

PARAGRAPH_SPLIT = re.compile(r"\n\s*\n")
FEATURES_RE = re.compile(r"config/features\s*=\s*PackedStringArray\((?P<items>.*?)\)", re.S)
VERSION_PATTERN = re.compile(r"^\d+\.\d+\.\d+\.[A-Za-z][\w]*\.\w+\.\w+$")


def _normalise(paragraph: str) -> str:
    return re.sub(r"\s+", " ", paragraph).strip().casefold()


def _duplicate_paragraphs(text: str, minimum: int) -> list[tuple[str, int]]:
    seen: dict[str, int] = {}
    duplicates: list[tuple[str, int]] = []
    for raw in PARAGRAPH_SPLIT.split(text):
        normalised = _normalise(raw)
        if len(normalised) < minimum:
            continue
        if normalised in seen:
            preview = " ".join(raw.split())[:80]
            duplicates.append((preview, seen[normalised]))
        else:
            seen[normalised] = len(normalised)
    return duplicates


def check() -> Result:
    result = Result(name=NAME)
    policy = load_policy()

    limit = int(policy["max_core_doc_chars"])
    core_docs: list[str] = policy["core_docs"]
    minimum = int(policy.get("duplicate_paragraph_min_chars", 20))

    # --- core documents: existence, budget, duplicate paragraphs -------------
    for doc in core_docs:
        path = ROOT / doc
        if not path.is_file():
            result.error(
                f"核心文档缺失: {doc}（要求 ≤{limit} 字符，需由负责人创建）"
            )
            continue
        text = read_text(path)
        length = len(text)
        if length > limit:
            result.error(f"{doc}: {length} 字符，超过上限 {limit}")
        result.note(f"{doc}: {length}/{limit} 字符")
        duplicates = _duplicate_paragraphs(text, minimum)
        for preview, _size in duplicates[:5]:
            result.error(f"{doc}: 重复段落（归一化后完全相同）: {preview}")

    # --- research documents: size warning + duplicate paragraph check --------
    warn_bytes = int(policy.get("research_doc_warn_bytes", 20480))
    research_files: list[Path] = []
    for pattern in policy.get("research_doc_globs", []):
        research_files.extend(sorted(ROOT.glob(pattern)))
    seen_paths: set[Path] = set()
    for path in research_files:
        if path in seen_paths or not path.is_file():
            continue
        seen_paths.add(path)
        rel = relative(path)
        size = path.stat().st_size
        if size > warn_bytes:
            result.warn(f"研究文档体积 {size} 字节 > {warn_bytes} 字节: {rel}")
        duplicates = _duplicate_paragraphs(read_text(path), minimum)
        for preview, _size in duplicates[:5]:
            result.error(f"{rel}: 重复段落（归一化后完全相同）: {preview}")
        result.note(f"{rel}: {size} 字节（研究文档，不限字数）")

    # --- version agreement: GODOT_VERSION.txt <-> project.godot <-> CI.md ---
    build = ""
    version_file = ROOT / policy.get("godot_version_file", "GODOT_VERSION.txt")
    if not version_file.is_file():
        result.error("GODOT_VERSION.txt 缺失")
    else:
        build = read_text(version_file).strip()
        if not VERSION_PATTERN.match(build):
            result.error(f"GODOT_VERSION.txt 格式异常: {build!r}")
    if build:
        family = ".".join(build.split(".")[:2])
        project_path = ROOT / "project.godot"
        if not project_path.is_file():
            result.error("project.godot 缺失")
        else:
            project_text = read_text(project_path)
            features = FEATURES_RE.search(project_text)
            if not features:
                result.error("project.godot 缺少 config/features=PackedStringArray(...)")
            else:
                declared = re.findall(r'"(\d+\.\d+)"', features.group("items"))
                if family not in declared:
                    result.error(
                        f"project.godot 特性行未声明 {family}（实际: {declared or '无版本特性'}），"
                        f"与 GODOT_VERSION.txt {build} 不一致"
                    )
                wrong = sorted({item for item in declared if item != family})
                if wrong:
                    result.error(
                        f"project.godot 声明了与 GODOT_VERSION.txt 冲突的版本特性: {wrong}"
                    )
                result.note(f"GODOT_VERSION.txt={build}; project.godot features={declared}")
        ci_md = ROOT / "CI.md"
        if not ci_md.is_file():
            result.error("CI.md 缺失")
        else:
            ci_text = read_text(ci_md)
            if build not in ci_text:
                result.error(f"CI.md 未记录锁定构建 {build}（需与 GODOT_VERSION.txt 一致）")
            pinned = str(policy.get("gdtoolkit_version", "")).strip()
            if pinned and pinned not in ci_text:
                result.error(f"CI.md 未记录固定版本 gdtoolkit {pinned}")
        for doc in policy.get("version_docs", []):
            path = ROOT / doc
            if not path.is_file():
                result.error(f"版本一致性文档缺失: {doc}")
            elif build not in read_text(path):
                result.error(f"{doc} 未记录锁定构建 {build}")
    return result


CHECKS = [(NAME, check)]


if __name__ == "__main__":
    import sys

    from ci_common import main_for_module

    sys.exit(main_for_module(CHECKS))

tools/ci/check_policy_tightening.py.text:
"""Policy tightening gate: rules may only get stricter over time.

Compared against the frozen policy copy in ``ci/baseline_snapshot.json`` (or
``git show BASE:ci/policy.json`` in the GitHub job).  The gate fails when the
current policy:

* raises an upper bound (document characters, file/line budgets, GDScript
  limits, duplicate block size, research document warning size, retry rounds);
* adds an allowed path/prefix that is not covered by the baseline whitelist;
* adds an asset ignore rule, research glob or versioned doc exemption;
* removes a CI policy path, core document or protected file from the policy;
* changes the policy approver or the pinned gdtoolkit version.
"""

from __future__ import annotations

import argparse
import json
import sys

from ci_common import BASELINE_PATH, POLICY_PATH, Result, load_json, load_policy, run

NAME = "policy_tightening"

UPPER_BOUND_KEYS = [
    "max_core_doc_chars",
    "max_changed_files",
    "max_diff_lines",
    "max_gdscript_lines",
    "max_cyclomatic_complexity",
    "duplicate_block_lines",
    "duplicate_paragraph_min_chars",
    "research_doc_warn_bytes",
    "max_rounds",
]
SUPERSET_KEYS = ["core_docs", "policy_paths", "version_docs"]
SUBSET_KEYS = ["asset_ignore_suffixes", "asset_ignore_files", "asset_ignore_prefixes"]
FROZEN_KEYS = ["policy_approver", "gdtoolkit_version"]


def _policy_at(revision: str) -> dict:
    completed = run(["git", "show", f"{revision}:ci/policy.json"], timeout=120)
    if completed.returncode != 0:
        raise RuntimeError(
            f"无法读取 {revision}:ci/policy.json: {completed.stderr.strip()[:300]}"
        )
    return json.loads(completed.stdout)


def _compare(previous: dict, current: dict, result: Result) -> None:
    for key in UPPER_BOUND_KEYS:
        if key not in previous:
            continue
        if key not in current:
            result.error(f"政策缺少阈值键（视同放宽）: {key}")
            continue
        try:
            if int(current[key]) > int(previous[key]):
                result.error(
                    f"{key} 只能持平或收紧: {previous[key]} -> {current[key]}"
                )
        except (TypeError, ValueError):
            result.error(f"{key} 不是整数: {current[key]!r}")

    for key in SUPERSET_KEYS:
        missing = sorted(set(previous.get(key, [])) - set(current.get(key, [])))
        if missing:
            result.error(f"{key} 移除了条目（放宽保护）: {', '.join(missing)}")

    for key in SUBSET_KEYS:
        added = sorted(set(current.get(key, [])) - set(previous.get(key, [])))
        if added:
            result.error(f"{key} 新增豁免（放宽检查）: {', '.join(added)}")

    for key in FROZEN_KEYS:
        if key in previous and current.get(key) != previous.get(key):
            result.error(
                f"{key} 已被固定，不得修改: {previous.get(key)!r} -> {current.get(key)!r}"
            )

    baseline_prefixes = list(previous.get("allowed_prefixes", []))
    for prefix in current.get("allowed_prefixes", []):
        covered = any(prefix == old or prefix.startswith(old) for old in baseline_prefixes)
        if not covered:
            result.error(f"新增白名单前缀（放宽范围）: {prefix}")

    baseline_files = set(previous.get("allowed_files", []))
    for path in current.get("allowed_files", []):
        if path in baseline_files:
            continue
        covered = any(path.startswith(old) for old in baseline_prefixes)
        if not covered:
            result.error(f"新增白名单文件（放宽范围）: {path}")

    for key in ("research_doc_globs",):
        added = sorted(set(current.get(key, [])) - set(previous.get(key, [])))
        if added:
            result.error(f"{key} 新增豁免（放宽字数检查）: {', '.join(added)}")


def check(base: str | None = None) -> Result:
    result = Result(name=NAME)
    current = load_policy()

    previous: dict | None = None
    mode = ""
    if base:
        try:
            previous = _policy_at(base)
            mode = f"git {base[:10]}"
        except RuntimeError as exc:
            result.error(str(exc))
            return result
    elif BASELINE_PATH.is_file():
        snapshot = load_json(BASELINE_PATH)
        previous = snapshot.get("policy")
        mode = "ci/baseline_snapshot.json"
    else:
        result.note("尚无政策基线快照：按首次基线引入处理（不阻断）")
        return result

    if not isinstance(previous, dict) or not previous:
        result.error("政策基线快照缺少 policy 内容")
        return result

    _compare(previous, current, result)
    result.note(
        f"对比 {mode}：阈值/白名单/豁免/固定项仅允许持平或收紧"
    )
    return result


CHECKS = [(NAME, check)]


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Policy tightening gate.")
    parser.add_argument("--base", default=None)
    args = parser.parse_args()
    gate = check(args.base)
    from ci_common import print_result

    print_result(gate, 0.0, verbose=True)
    sys.exit(0 if gate.ok else 1)

tools/ci/check_protected_tests.py.text:
"""Protected regression test gate.

``tests/protected_test_cases.json`` is the authoritative list of behaviour
assertions that must survive every change.  The gate fails when:

* a listed case id is missing from the manifest (deleted or renamed),
* a listed case id is no longer present in its test file (weakend/removed),
* a protected test file listed in the frozen baseline snapshot is deleted.

New test files that are not yet registered produce warnings so they can be
added without blocking unrelated work.
"""

from __future__ import annotations

import sys
from pathlib import Path

from ci_common import (
    BASELINE_PATH,
    ROOT,
    Result,
    load_json,
    load_policy,
    read_text,
    relative,
    run,
)

NAME = "protected_tests"
MANIFEST_PATH = ROOT / "tests/protected_test_cases.json"


def _manifest_files(result: Result) -> dict[str, list[str]]:
    if not MANIFEST_PATH.is_file():
        result.error(f"受保护测试清单缺失: {relative(MANIFEST_PATH)}")
        return {}
    data = load_json(MANIFEST_PATH)
    files: dict[str, list[str]] = {}
    for path, cases in (data.get("files") or {}).items():
        files[str(path)] = [str(case) for case in cases]
    legacy_file = data.get("file")
    if legacy_file:
        bucket = files.setdefault(str(legacy_file), [])
        for case in data.get("required_assertions", []):
            if case not in bucket:
                bucket.append(str(case))
    if not files:
        result.error("受保护测试清单没有任何用例（files 为空）")
    return files


def _baseline() -> dict:
    if not BASELINE_PATH.is_file():
        return {}
    return load_json(BASELINE_PATH)


def _git_deleted_tests(result: Result, base: str, head: str) -> None:
    completed = run(["git", "diff", "--name-status", f"{base}...{head}"], timeout=120)
    if completed.returncode != 0:
        result.error(f"git diff 失败（{base}...{head}）: {completed.stderr.strip()[:300]}")
        return
    for row in (completed.stdout or "").splitlines():
        parts = row.split("\t")
        if len(parts) < 2:
            continue
        status, path = parts[0].strip(), parts[1].strip()
        if status.startswith("D") and path.startswith("tests/") and path.endswith(".gd"):
            result.error(f"测试文件被删除（需人工复核）: {path}")


def check(base: str | None = None, head: str | None = None) -> Result:
    result = Result(name=NAME)
    load_policy()
    files = _manifest_files(result)

    # --- 1. manifest cases must still exist inside their test files ---------
    total_cases = 0
    for path, cases in files.items():
        total_cases += len(cases)
        file_path = ROOT / path
        if not cases:
            result.warn(f"{path} 未登记任何受保护用例")
        if not file_path.is_file():
            result.error(f"受保护测试文件缺失: {path}")
            continue
        source = read_text(file_path)
        for case in cases:
            if f'"{case}"' not in source and case not in source:
                result.error(f"受保护用例缺失/被弱化: {path} :: {case}")

    # --- 2. frozen baseline: cases and test files may only grow -------------
    snapshot = _baseline()
    baseline_cases = snapshot.get("protected_cases", {})
    if baseline_cases:
        for path, cases in baseline_cases.items():
            if path not in files:
                result.error(f"保护清单删除了受保护测试文件: {path}")
            else:
                missing = [case for case in cases if case not in files[path]]
                for case in missing:
                    result.error(f"受保护用例被删除: {path} :: {case}")
    for path in snapshot.get("test_files", []):
        if not (ROOT / path).is_file():
            result.error(f"测试文件被删除（基线中存在）: {path}")

    # --- 3. warn about unprotected new tests --------------------------------
    tests_dir = ROOT / "tests"
    if tests_dir.is_dir():
        for file_path in sorted(tests_dir.rglob("test_*.gd")):
            rel = relative(file_path)
            if rel not in files:
                result.warn(f"新增测试未纳入保护清单（建议登记用例 id）: {rel}")

    # --- 4. optional git history mode (used by the GitHub Actions job) ------
    if base and head:
        _git_deleted_tests(result, base, head)

    result.note(f"{len(files)} 个测试文件 / {total_cases} 个受保护用例")
    return result


CHECKS = [(NAME, check)]


if __name__ == "__main__":
    import argparse

    from ci_common import main_for_module

    parser = argparse.ArgumentParser(description="Protected test case gate.")
    parser.add_argument("--base", default=None)
    parser.add_argument("--head", default=None)
    args, _unknown = parser.parse_known_args()
    if args.base and args.head:
        sys.exit(main_for_module([(NAME, lambda: check(args.base, args.head))]))
    sys.exit(main_for_module(CHECKS))

tools/ci/check_scope.py.text:
"""Change scope gate.

Two modes are supported:

* ``--base SHA --head SHA`` - authoritative git diff used by GitHub Actions;
* local mode - compare the working tree against the frozen baseline snapshot
  ``ci/baseline_snapshot.json`` (the project is not a git repository yet).
  When no snapshot exists the run is treated as the first baseline
  introduction and does not block.

Both modes enforce the whitelist in ``ci/policy.json`` plus the file and line
budgets.  Changes to CI policy paths are reported but not failed locally:
approval is enforced by the ``policy-approval`` GitHub Actions job.
"""

from __future__ import annotations

import argparse
import difflib
import sys
from pathlib import Path

from ci_common import (
    BASELINE_PATH,
    ROOT,
    Result,
    count_lines,
    iter_project_files,
    load_json,
    load_policy,
    read_text,
    relative,
    run,
    sha256_bytes,
)

NAME = "scope"
SNAPSHOT_SELF = BASELINE_PATH


def _is_allowed(path: str, policy: dict) -> bool:
    if path in policy.get("allowed_files", []):
        return True
    return any(path.startswith(prefix) for prefix in policy.get("allowed_prefixes", []))


def _diff_lines(before: str, after: str) -> int:
    matcher = difflib.SequenceMatcher(a=before.splitlines(), b=after.splitlines())
    total = 0
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == "equal":
            continue
        total += (i2 - i1) + (j2 - j1)
    return total


def _git_changes(base: str, head: str) -> tuple[list[str], int]:
    inside = run(["git", "rev-parse", "--is-inside-work-tree"], timeout=60)
    if inside.returncode != 0:
        raise RuntimeError("当前目录不是 git 仓库，无法使用 --base/--head 模式")
    names = run(
        ["git", "diff", "--name-only", "-z", f"{base}...{head}"], timeout=120
    )
    if names.returncode != 0:
        raise RuntimeError(f"git diff --name-only 失败: {names.stderr.strip()[:300]}")
    paths = [path for path in (names.stdout or "").split("\0") if path]
    numstat = run(["git", "diff", "--numstat", f"{base}...{head}"], timeout=120)
    changed_lines = 0
    for row in (numstat.stdout or "").splitlines():
        parts = row.split("\t")
        if len(parts) < 2:
            continue
        for token in parts[:2]:
            if token.isdigit():
                changed_lines += int(token)
    return paths, changed_lines


def _snapshot_changes() -> tuple[list[str], list[str], list[str], int] | None:
    if not BASELINE_PATH.is_file():
        return None
    snapshot = load_json(BASELINE_PATH)
    baseline_files: dict[str, dict] = snapshot.get("files", {})
    current: dict[str, dict] = {}
    for path in iter_project_files():
        if path == SNAPSHOT_SELF:
            continue
        rel = relative(path)
        try:
            payload = path.read_bytes()
        except OSError:
            continue
        entry: dict = {"sha256": sha256_bytes(payload), "lines": 0}
        try:
            text = payload.decode("utf-8")
            entry["text"] = text
            entry["lines"] = count_lines(text)
        except UnicodeDecodeError:
            entry["binary"] = True
        current[rel] = entry

    added = sorted(set(current) - set(baseline_files))
    deleted = sorted(set(baseline_files) - set(current))
    modified = sorted(
        rel
        for rel in set(current) & set(baseline_files)
        if current[rel]["sha256"] != baseline_files[rel].get("sha256")
    )

    changed_lines = 0
    for rel in added:
        changed_lines += current[rel]["lines"]
    for rel in deleted:
        changed_lines += int(baseline_files[rel].get("lines", 0))
    for rel in modified:
        before = baseline_files[rel].get("text")
        after = current[rel].get("text")
        if before is None or after is None:
            changed_lines += int(baseline_files[rel].get("lines", 0)) + current[rel][
                "lines"
            ]
        else:
            changed_lines += _diff_lines(before, after)
    return added, deleted, modified, changed_lines


def check(base: str | None = None, head: str | None = None) -> Result:
    result = Result(name=NAME)
    policy = load_policy()

    if base and head:
        try:
            paths, changed_lines = _git_changes(base, head)
        except RuntimeError as exc:
            result.error(str(exc))
            return result
        mode = f"git {base[:10]}...{head[:10]}"
    else:
        snapshot = _snapshot_changes()
        if snapshot is None:
            result.note(
                "首次引入基线快照：跳过范围阻断（基线引入不阻断），"
                "请用 python tools/ci/baseline.py --trusted 建立基线"
            )
            return result
        added, deleted, modified, changed_lines = snapshot
        paths = added + deleted + modified
        mode = f"baseline snapshot（新增 {len(added)} / 删除 {len(deleted)} / 修改 {len(modified)}）"

    outside = [path for path in paths if not _is_allowed(path, policy)]
    for path in outside[:20]:
        result.error(f"改动超出白名单: {path}")
    if len(outside) > 20:
        result.error(f"... 其余 {len(outside) - 20} 个越界文件未逐条列出")

    max_files = int(policy["max_changed_files"])
    max_lines = int(policy["max_diff_lines"])
    if len(paths) > max_files:
        result.error(f"改动文件数 {len(paths)} 超过预算 {max_files}")
    if changed_lines > max_lines:
        result.error(f"增删行数 {changed_lines} 超过预算 {max_lines}")

    protected_paths = policy.get("policy_paths", [])
    touched = [
        path
        for path in paths
        if any(path == item or path.startswith(item) for item in protected_paths)
    ]
    if touched:
        result.warn(
            "本次改动涉及 CI/政策/测试保护文件，需 policy_approver 在 PR 当前 head 上批准: "
            + ", ".join(sorted(touched)[:8])
        )

    result.note(
        f"{mode}: {len(paths)} 文件 / {changed_lines} 行增删 "
        f"（预算 {max_files} 文件 / {max_lines} 行）"
    )
    return result


CHECKS = [(NAME, check)]


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Scope gate.")
    parser.add_argument("--base", default=None)
    parser.add_argument("--head", default=None)
    args = parser.parse_args()
    gate = check(args.base, args.head)
    from ci_common import print_result

    print_result(gate, 0.0, verbose=True)
    sys.exit(0 if gate.ok else 1)

tools/ci/check_unused_scripts.py.text:
"""Unreferenced script gate: every first-party ``.gd`` must be reachable.

A script counts as referenced when:

* its ``res://scripts/...gd`` path appears in another project file (scene,
  autoload settings, test, docs or CI config), or
* it declares ``class_name`` and that class name is used elsewhere.
"""

from __future__ import annotations

import re

from ci_common import ROOT, Result, TEXT_SUFFIXES, iter_project_files, read_text, relative

NAME = "unused_scripts"
CLASS_NAME_RE = re.compile(r"^\s*class_name\s+([A-Za-z_]\w*)\s*$", re.M)


def check() -> Result:
    result = Result(name=NAME)

    script_root = ROOT / "scripts"
    scripts = sorted(script_root.rglob("*.gd")) if script_root.is_dir() else []
    if not scripts:
        result.error("scripts/ 下未找到任何 .gd 脚本")
        return result

    corpus: list[tuple[str, str]] = []
    for path in iter_project_files():
        if path.suffix.lower() not in TEXT_SUFFIXES:
            continue
        try:
            corpus.append((relative(path), read_text(path)))
        except (OSError, UnicodeDecodeError):
            continue

    class_names: dict[str, str] = {}
    for path in scripts:
        match = CLASS_NAME_RE.search(read_text(path))
        if match:
            class_names[relative(path)] = match.group(1)

    unused: list[str] = []
    for path in scripts:
        rel = relative(path)
        resource_path = "res://" + rel
        referenced = False
        for other_rel, text in corpus:
            if other_rel == rel:
                continue
            if resource_path in text:
                referenced = True
                break
        if not referenced and rel in class_names:
            name = class_names[rel]
            pattern = re.compile(rf"\b{re.escape(name)}\b")
            for other_rel, text in corpus:
                if other_rel == rel:
                    continue
                if pattern.search(text):
                    referenced = True
                    break
        if not referenced:
            unused.append(rel)

    for rel in unused:
        result.error(f"脚本未被引用（res:// 引用扫描未命中）: {rel}")
    if unused:
        result.error(
            "请删除孤儿脚本，或让场景/自动加载/其它脚本/测试显式引用它"
        )
    result.note(f"扫描 {len(scripts)} 个 scripts/*.gd，未引用 {len(unused)} 个")
    return result


CHECKS = [(NAME, check)]


if __name__ == "__main__":
    import sys

    from ci_common import main_for_module

    sys.exit(main_for_module(CHECKS))

tools/ci/ci_common.py.text:
"""Shared helpers for the local CI gates.

All gates live in ``tools/ci`` and are imported by ``run_local.py``.  Each
gate module exposes ``CHECKS``: a list of ``(name, callable)`` pairs where the
callable returns a :class:`Result`.  Standalone execution is supported through
``python tools/ci/<gate>.py``.

The configuration lives in ``ci/policy.json`` and is compared with the frozen
baseline in ``ci/baseline_snapshot.json`` by the tightening gate.  No gate may
write to source directories; the only writes performed by this toolchain are
the baseline snapshot (explicitly human approved) and optional evidence logs
inside the system temporary directory.
"""

from __future__ import annotations

import json
import os
import re
import shutil
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Iterable, Iterator

ROOT = Path(__file__).resolve().parents[2]
CI_DIR = ROOT / "ci"
POLICY_PATH = CI_DIR / "policy.json"
BASELINE_PATH = CI_DIR / "baseline_snapshot.json"

# Directories that never contain project source we gate on.
EXCLUDED_DIRS = {
    ".git",
    ".godot",
    ".ci-venv",
    "__pycache__",
    ".dsh-rollback",
    ".svn",
}
EXCLUDED_SUFFIXES = {".pyc", ".pyo", ".tmp", ".log"}
TEXT_SUFFIXES = {
    ".gd",
    ".tscn",
    ".tres",
    ".godot",
    ".cfg",
    ".md",
    ".json",
    ".yml",
    ".yaml",
    ".py",
    ".txt",
    ".sh",
    ".import",
    ".gdignore",
    ".gitignore",
    ".gitattributes",
    ".editorconfig",
    ".csv",
}

ANSI_RE = re.compile(r"\x1b\[[0-9;?]*[A-Za-z]")


@dataclass
class Result:
    """Outcome of a single CI gate."""

    name: str = ""
    errors: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.errors

    def error(self, message: str) -> None:
        self.errors.append(str(message))

    def warn(self, message: str) -> None:
        self.warnings.append(str(message))

    def note(self, message: str) -> None:
        self.notes.append(str(message))


def fail(module: str, message: str) -> Result:
    """Build an immediate failure result (used for missing prerequisites)."""
    result = Result(name=module)
    result.error(message)
    return result


def load_policy() -> dict:
    if not POLICY_PATH.is_file():
        raise FileNotFoundError(f"missing CI policy file: {relative(POLICY_PATH)}")
    return json.loads(POLICY_PATH.read_text(encoding="utf-8"))


def load_json(path: Path) -> dict:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def relative(path: Path) -> str:
    try:
        return Path(path).resolve().relative_to(ROOT).as_posix()
    except ValueError:
        return str(path)


def read_text(path: Path) -> str:
    return Path(path).read_text(encoding="utf-8")


def iter_project_files(suffixes: Iterable[str] | None = None) -> Iterator[Path]:
    """Yield project files, skipping caches, virtualenvs and git metadata."""
    wanted = {suffix.lower() for suffix in suffixes} if suffixes else None
    for base, dirs, files in os.walk(ROOT):
        dirs[:] = sorted(d for d in dirs if d not in EXCLUDED_DIRS)
        for name in sorted(files):
            path = Path(base) / name
            if path.suffix.lower() in EXCLUDED_SUFFIXES and path.suffix.lower() != ".log":
                continue
            if wanted is not None and path.suffix.lower() not in wanted:
                continue
            yield path


def strip_ansi(text: str) -> str:
    return ANSI_RE.sub("", text or "")


def excerpt(text: str, max_lines: int = 20, max_chars: int = 4000) -> str:
    """Return a compact, ANSI-free excerpt suitable for a failure message."""
    cleaned = strip_ansi(text or "").replace("\r\n", "\n").strip()
    lines = [line for line in cleaned.splitlines() if line.strip()]
    trimmed = lines[:max_lines]
    if len(lines) > max_lines:
        trimmed.append(f"... ({len(lines) - max_lines} more lines)")
    joined = "\n".join(trimmed)
    if len(joined) > max_chars:
        joined = joined[:max_chars] + "..."
    return joined


def run(
    command: list[str],
    cwd: Path = ROOT,
    timeout: float | None = 300,
    extra_env: dict[str, str] | None = None,
) -> subprocess.CompletedProcess:
    """Run a command with captured UTF-8 output."""
    env = os.environ.copy()
    env.setdefault("PYTHONIOENCODING", "utf-8")
    if extra_env:
        env.update(extra_env)
    return subprocess.run(
        [str(part) for part in command],
        cwd=str(cwd),
        text=True,
        encoding="utf-8",
        errors="replace",
        capture_output=True,
        timeout=timeout,
        env=env,
    )


def sha256_bytes(payload: bytes) -> str:
    import hashlib

    return hashlib.sha256(payload).hexdigest()


def count_lines(text: str) -> int:
    return len(text.splitlines())


def resolve_godot(policy: dict | None = None) -> tuple[str | None, list[str]]:
    """Locate the Godot binary.

    Order is fixed by the policy: ``$env:GODOT``, the pinned Windows console
    executable, the non-console fallback and finally entries on ``PATH``.
    """
    policy = policy or load_policy()
    candidates = policy.get(
        "godot_candidates",
        [
            "$GODOT",
            r"D:\app_finish\Godot\Godot_v4.7.2-stable_win64_console.exe",
            r"D:\app_finish\Godot\Godot_v4.7.2-stable_win64.exe",
            "godot",
            "godot4",
            "$GODOT_BIN",
        ],
    )
    tried: list[str] = []
    for raw in candidates:
        if raw.startswith("$"):
            name = raw[1:]
            value = os.environ.get(name, "").strip()
            if not value:
                tried.append(f"{raw}=<unset>")
                continue
            tried.append(f"{raw}={value}")
            candidate = Path(value)
            if candidate.is_file():
                return str(candidate), tried
            found = shutil.which(value)
            if found:
                return found, tried
            continue
        tried.append(raw)
        candidate = Path(raw)
        if candidate.is_file():
            return str(candidate), tried
        found = shutil.which(raw)
        if found:
            return found, tried
    return None, tried


def resolve_gdtoolkit_tool(name: str) -> tuple[str | None, str]:
    """Return (path, source) for gdtoolkit console scripts.

    Prefers the project-local ``.ci-venv`` so the pinned version is used on
    developer machines; the GitHub runner installs the same pin globally and
    falls back to ``PATH``.
    """
    venv_bin = ROOT / ".ci-venv" / ("Scripts" if os.name == "nt" else "bin")
    for suffix in (".exe", ""):
        candidate = venv_bin / f"{name}{suffix}"
        if candidate.is_file():
            return str(candidate), relative(candidate)
    found = shutil.which(name)
    if found:
        return found, "PATH"
    return None, "missing"


def tool_version(executable: str) -> str:
    try:
        completed = run([executable, "--version"], timeout=60)
    except (OSError, subprocess.SubprocessError):
        return ""
    output = strip_ansi((completed.stdout or "") + (completed.stderr or "")).strip()
    return output.splitlines()[0].strip() if output else ""


def godot_version(executable: str) -> str:
    try:
        completed = run([executable, "--version"], timeout=60)
    except (OSError, subprocess.SubprocessError):
        return ""
    output = strip_ansi((completed.stdout or "") + (completed.stderr or "")).strip()
    for line in output.splitlines():
        match = re.search(r"\d+\.\d+\.\d+\.[A-Za-z]+\.\w+\.\w+", line)
        if match:
            return match.group(0)
    return output.splitlines()[0].strip() if output else ""


def expected_godot_build(policy: dict | None = None) -> str:
    policy = policy or load_policy()
    version_file = ROOT / policy.get("godot_version_file", "GODOT_VERSION.txt")
    if not version_file.is_file():
        return ""
    return version_file.read_text(encoding="utf-8").strip()


def python_version() -> str:
    return f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}"


def gdtoolkit_version(policy: dict) -> str:
    return str(policy.get("gdtoolkit_version", ""))


def print_result(result: Result, elapsed: float, verbose: bool = False) -> None:
    """Print one gate line plus its problems."""
    status = "PASS" if result.ok else "FAIL"
    print(f"{status}  {result.name}  ({elapsed:.2f}s)", flush=True)
    for warning in result.warnings:
        print(f"      WARN: {warning}", flush=True)
    for error in result.errors:
        for index, line in enumerate(str(error).splitlines()):
            prefix = "      - " if index == 0 else "        "
            print(f"{prefix}{line}", flush=True)
    if verbose:
        for note in result.notes:
            print(f"      note: {note}", flush=True)


def main_for_module(checks: list[tuple[str, object]]) -> int:
    """Default ``__main__`` behaviour shared by every gate module."""
    import argparse

    parser = argparse.ArgumentParser(description="Run one CI gate.")
    parser.add_argument("--verbose", "-v", action="store_true")
    args = parser.parse_args()
    failures = 0
    for name, func in checks:
        import time

        started = time.perf_counter()
        try:
            result = func()  # type: ignore[operator]
        except Exception as exc:  # noqa: BLE001 - gate must not crash silently
            result = Result(name=name, errors=[f"gate crashed: {exc.__class__.__name__}: {exc}"])
        result.name = name
        print_result(result, time.perf_counter() - started, verbose=args.verbose)
        failures += 0 if result.ok else 1
    return 0 if failures == 0 else 1
